#include <esp_err.h>
#include <esp_ota_ops.h>

esp_err_t confirmPendingImage(bool healthChecksPassed) {
  const esp_partition_t* running = esp_ota_get_running_partition();
  if (running == nullptr) return ESP_ERR_NOT_FOUND;

  esp_ota_img_states_t state;
  const esp_err_t stateResult = esp_ota_get_state_partition(running, &state);
  if (stateResult != ESP_OK) return stateResult;
  if (state != ESP_OTA_IMG_PENDING_VERIFY) return ESP_OK;

  if (!healthChecksPassed) {
    return esp_ota_mark_app_invalid_rollback_and_reboot();
  }
  return esp_ota_mark_app_valid_cancel_rollback();
}
